use hs_loop::ledger::Ledger;use serde_json::json;
#[test]fn native_foreground_records_exit_and_stream_evidence(){let mut l=Ledger::default();l.apply_tool_call(1,"bash",&json!({"command":"test -f result.txt; od -c result.txt"}),&json!({"kind":"foreground","exitCode":0,"stdout":{"text":"job done"},"stderr":{"text":"warning"},"signal":null}));assert!(l.model_verified());let s=l.summary();assert!(s.contains("exit=0")&&s.contains("job done")&&s.contains("warning"),"{s}");}
#[test]fn native_jobs_record_only_collected_settled_evidence(){let mut l=Ledger::default();for status in ["running","stopping"]{l.apply_tool_call(1,"job_output",&json!({"job_id":"a"}),&json!({"job":{"id":"a","status":status},"text":"partial"}));assert!(!l.model_verified());}l.apply_tool_call(2,"job_output",&json!({"job_id":"a"}),&json!({"job":{"id":"a","label":"check","status":"completed"},"text":"alpha\nomega\n"}));assert!(l.model_verified());let s=l.summary();assert!(s.contains("alpha omega")&&s.contains("PASS"),"{s}");}
#[test]fn promoted_background_and_failed_launch_do_not_count(){let mut l=Ledger::default();for v in [json!({"kind":"promoted","output":"x","jobId":"a"}),json!({"kind":"background","jobId":"b"}),json!({"error":"launch failed","exitCode":0})]{l.apply_tool_call(1,"bash",&json!({"command":"check"}),&v);assert!(!l.model_verified());}}
#[test]fn launch_and_delta_collection_evidence_survives(){let mut l=Ledger::default();l.apply_tool_call(1,"bash",&json!({"command":"echo alpha; echo omega","run_in_background":true}),&json!({"kind":"background","jobId":"a"}));assert!(l.summary().contains("background"));l.apply_tool_call(2,"job_output",&json!({"job_id":"a"}),&json!({"job":{"id":"a","status":"running"},"text":"alpha\n"}));l.apply_tool_call(3,"job_output",&json!({"job_id":"a"}),&json!({"job":{"id":"a","status":"completed"},"text":"omega\n"}));let s=l.summary();assert!(s.contains("alpha omega")&&s.contains("echo alpha"),"{s}");}
